 26	    private Node insertAsBinarySearchTreeNode(int data) {
 27	        Node parent = null;
 28	        Node current = root;
 29	
 30	        while (current != null) {
 31	            parent = current;
 32	            current = data < current.data ? current.left : current.right;
 33	        }
 34	
 35	        Node insertedNode = new Node(data);
 36	        insertedNode.parent = parent;
